1	// Runs the benchmark pipeline: refresh provider pricing, fetch Artificial Analysis
2	// data, update config/model-mapping.json, then score models. See README for how the
3	// mapping is maintained and how broken parsers are repaired locally.
4	
5	import { fetchArtificialAnalysisData } from "./artificial-analysis/fetch.ts";
6	import { updateModelMapping } from "./mapping/update-mapping.ts";
7	import { refreshPricingSource } from "./pricing/refresh.ts";
8	import { pricingSources } from "./pricing/sources.ts";
9	import { computeScores } from "./scoring/compute-scores.ts";
10	
11	const totalSteps = pricingSources.length + 3;
12	let step = 0;
13	const logStep = (label: string) =>
14	  console.log(`${step > 0 ? "\n" : ""}== Step ${++step}/${totalSteps}: ${label} ==`);
15	
16	try {
17	  if (!process.env.AA_API_KEY) {
18	    console.error(
19	      "Missing AA_API_KEY. Locally, copy .env.example to .env and fill it in; in CI, set the AA_API_KEY repository secret.",
20	    );
21	    process.exit(1);
22	  }
23	
24	  const failedSources: string[] = [];
25	  for (const source of pricingSources) {
26	    logStep(`refreshing ${source.displayName} pricing`);
27	    if (!(await refreshPricingSource(source))) failedSources.push(source.displayName);
28	  }
29	
30	  logStep("fetching Artificial Analysis benchmark data");
31	  await fetchArtificialAnalysisData();
32	
33	  logStep("updating model mapping");
34	  await updateModelMapping();
35	
36	  logStep("scoring models per category");
37	  await computeScores();
38	
39	  if (failedSources.length > 0) {
40	    console.error(
41	      `\nDone with parser failures (${failedSources.join(", ")}); some pricing data is stale or missing (see errors above).`,
42	    );
43	    process.exitCode = 1;
44	  } else {
45	    console.log("\nDone. See data/recommendations.json.");
46	  }
47	} catch (err) {
48	  console.error(err);
49	  process.exit(1);
50	}
