1	import { mkdir, writeFile } from "node:fs/promises";
2	import path from "node:path";
3	import { downloadHtml } from "./downloader.ts";
4	import { repairParser } from "./repair-parser.ts";
5	import type { PricingSource } from "./source.ts";
6	
7	// Returns false when parsing failed and could not be repaired (existing data file is left
8	// untouched). Network errors are not caught and abort the pipeline.
9	export async function refreshPricingSource<Row>(source: PricingSource<Row>): Promise<boolean> {
10	  const html = await downloadHtml(source.sourceUrl);
11	
12	  let models: Row[];
13	  try {
14	    models = source.parse(html);
15	  } catch (error) {
16	    const repaired = await repairParser({ source, html, error });
17	    if (!repaired) return false;
18	    models = repaired;
19	  }
20	
21	  await mkdir(path.dirname(source.outFile), { recursive: true });
22	  await writeFile(
23	    source.outFile,
24	    JSON.stringify(
25	      {
26	        sourceUrl: source.sourceUrl,
27	        fetchedAt: new Date().toISOString(),
28	        notes: source.notes,
29	        models,
30	      },
31	      null,
32	      2,
33	    ),
34	  );
35	  console.log(`Wrote ${models.length} ${source.displayName} models to ${source.outFile}`);
36	  return true;
37	}
